import { forwardRef } from 'react';

interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: 'default' | 'success' | 'warning' | 'error' | 'info' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  dot?: boolean;
}

export const Badge = forwardRef<HTMLSpanElement, BadgeProps>(
  ({ className = '', variant = 'default', size = 'md', dot = false, children, ...props }, ref) => {
    const variants = {
      default: 'bg-violet-500/20 text-violet-300 border border-violet-500/30',
      success: 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30',
      warning: 'bg-amber-500/20 text-amber-300 border border-amber-500/30',
      error: 'bg-rose-500/20 text-rose-300 border border-rose-500/30',
      info: 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30',
      outline: 'bg-transparent text-gray-300 border border-white/20',
    };
    const sizes = {
      sm: 'px-2 py-0.5 text-xs',
      md: 'px-2.5 py-1 text-sm',
      lg: 'px-3 py-1.5 text-base',
    };

    return (
      <span
        ref={ref}
        className={`inline-flex items-center gap-1.5 rounded-full border font-medium ${variants[variant]} ${sizes[size]} ${className}`}
        {...props}
      >
        {dot && (
          <span
            className={`w-1.5 h-1.5 rounded-full ${
              variant === 'success' ? 'bg-emerald-400' :
              variant === 'warning' ? 'bg-amber-400' :
              variant === 'error' ? 'bg-rose-400' :
              variant === 'info' ? 'bg-cyan-400' :
              variant === 'outline' ? 'bg-gray-400' :
              'bg-violet-400'}
            `}
          />
        )}
        {children}
      </span>
    );
  }
);
Badge.displayName = 'Badge';
